import app from 'flarum/forum/app';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import BadgesBasePage from './BadgesBasePage';
import BadgeCard from './BadgeCard';
import { GROUPINGS, LIST_FIELDS, badgesEnabled, loadOwnedBadgeIds } from '../utils';
import { t } from '../../../utils/settings';

/**
 * A página /badges: os emblemas em grade, separados por
 * agrupamento (Primeiros passos, Comunidade, Postando, Nível de confiança),
 * cada um com quantas vezes foi concedido. Os que a pessoa logada já tem
 * ganham a marca de conquistado.
 */
export default class BadgesPage extends BadgesBasePage {
  badges = null;
  owned = new Set();
  oninit(vnode) {
    super.oninit(vnode);
    if (!badgesEnabled()) return;
    app.store.find('canela-badges', {
      sort: 'position',
      fields: {
        'canela-badges': LIST_FIELDS
      }
    }).then(badges => this.badges = badges.slice()).catch(() => this.badges = []).finally(() => m.redraw());
    const user = app.session.user;
    if (user) {
      loadOwnedBadgeIds(user).then(ids => {
        this.owned = ids;
        m.redraw();
      });
    }
  }
  title() {
    return t('badges.page_title');
  }
  className() {
    return 'CanelaBadgesIndex';
  }
  content() {
    return m("div", {
      className: "CanelaBadgesPage"
    }, m("h1", {
      className: "CanelaBadges-title"
    }, t('badges.page_title')), this.badges === null ? m(LoadingIndicator, {
      display: "block"
    }) : this.groups());
  }
  groups() {
    const badges = this.badges;
    if (!badges.length) return m("p", {
      className: "CanelaBadges-empty"
    }, t('badges.none'));

    // Um agrupamento que não está na lista (emblema criado à mão) cai em "Outros".
    const groupOf = badge => GROUPINGS.includes(badge.grouping()) ? badge.grouping() : 'other';

    // Só os grupos com emblemas: um `null` no meio de itens com `key` faz o
    // Mithril recusar a lista inteira.
    return GROUPINGS.filter(grouping => badges.some(badge => groupOf(badge) === grouping)).map(grouping => {
      const inGroup = badges.filter(badge => groupOf(badge) === grouping);
      return m("section", {
        className: "CanelaBadges-group",
        key: grouping
      }, m("h2", {
        className: "CanelaBadges-groupTitle"
      }, t(`badges.groupings.${grouping}`)), m("ul", {
        className: "CanelaBadges-grid"
      }, inGroup.map(badge => m("li", {
        key: badge.id()
      }, m(BadgeCard, {
        badge: badge,
        showCount: true,
        owned: this.owned.has(badge.id())
      })))));
    });
  }
}
flarum.reg.add('ramon-canela', 'forum/features/badges/components/BadgesPage', BadgesPage);